parameters.text:
=Write the complete article now, following all system rules exactly, for this title/keyword:
{{ $json.Title }}

The article must have exactly 8 H2 sections and exactly 8 [image space] placeholders. Return only the final HTML article.

parameters.jsCode:
// ================================================
// 1. EXTRACT MEDIA URLS & IDS FROM INPUT
// ================================================
let mediaUrls = [];
let mediaIds = [];
let featuredMediaId = 0;

try {
  const inputItems = $input.all();
  mediaUrls = inputItems.map(item => item.json?.guid?.rendered || item.json?.source_url || item.json?.url).filter(Boolean);
  mediaIds = inputItems.map(item => item.json?.id).filter(Boolean);

  if (mediaIds.length > 0) {
    featuredMediaId = mediaIds[0];
  }
} catch (e) {
  // Fallbacks stay empty
}

// ================================================
// 2. EXTRACT ARTICLE CONTENT FROM 'write the article'
// ================================================
let rawArticleText = '';
try {
  rawArticleText = $('write the article').first()?.json?.text || '';
} catch (e) {
  rawArticleText = '';
}

// ================================================
// 3. EXTRACT SEO TITLE & METADATA
// ================================================
let seoTitle = '';
let metaDesc = '';
try {
  const seoData = $('generate seo meta data').first()?.json || {};
  const seoObj = (seoData.output && typeof seoData.output === 'object') ? seoData.output : seoData;
  seoTitle = seoObj.title || '';
  metaDesc = seoObj.meta_description || seoObj.description || '';
} catch (e) {
  seoTitle = '';
  metaDesc = '';
}

// ================================================
// 4. REPLACE PLACEHOLDERS WITH RESPONSIVE IMAGES
// ================================================
let formattedContent = rawArticleText;
if (mediaUrls.length > 0 && formattedContent) {
  let imageIndex = 0;
  formattedContent = formattedContent.replace(/\[image\s*space\]|\[image[^\]]*\]/gi, () => {
    if (imageIndex < mediaUrls.length) {
      const url = mediaUrls[imageIndex];
      imageIndex++;
      return `<figure class="wp-block-image"><img src="${url}" alt="Article Image ${imageIndex}" style="max-width:100%;height:auto;display:block;margin:0 auto;" /></figure>`;
    }
    return '';
  });
}

// Catch-all: If HTML <img> tags already exist in the text without inline width constraints, enforce responsive styling
if (formattedContent) {
  formattedContent = formattedContent.replace(/<img (?!.*?style=)/gi, '<img style="max-width:100%;height:auto;display:block;margin:0 auto;" ');
}

// ================================================
// 5. OUTPUT SINGLE PAYLOAD FOR WORDPRESS
// ================================================
return [{
  json: {
    title: seoTitle,
    content: formattedContent,
    status: 'draft',
    featured_media: featuredMediaId,
    meta: {
      _yoast_wpseo_metadesc: metaDesc,
      _rank_math_description: metaDesc
    },
    all_media_ids: mediaIds,
    all_media_urls: mediaUrls
  }
}];

// Retrieve output string or object from previous node
let raw = $input.first().json.text || $input.first().json.output || $input.first().json.content || $input.first().json || '';
let prompts = [];

// If the output is already an array of strings or objects
if (Array.isArray(raw)) {
  prompts = raw.map(p => typeof p === 'object' ? (p.prompt || JSON.stringify(p)) : p);
} else {
  // Convert object to string if necessary
  if (typeof raw === 'object') {
    raw = JSON.stringify(raw);
  }

  // 1. Clean markdown code fences
  let clean = raw.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();

  // 2. Try JSON Parsing first
  try {
    const match = clean.match(/\[[\s\S]*\]/);
    const parsed = JSON.parse(match ? match[0] : clean);
    if (Array.isArray(parsed)) {
      prompts = parsed;
    }
  } catch (e) {
    // 3. Regex fallback: Find text enclosed in double quotes
    const stringMatches = [...clean.matchAll(/"([^"\\]*(?:\\.[^"\\]*)*)"/g)];
    if (stringMatches.length > 0) {
      prompts = stringMatches.map(m => m[1]);
    }
  }

  // 4. Line-by-line fallback: Split text lines (handles numbered/bulleted lists & plain text)
  if (prompts.length === 0) {
    prompts = clean
      .split('\n')
      .map(p => p.replace(/^[\d+.\-* ]+/, '').trim()) // Strip list numbers/bullets
      .filter(p => p.length > 0 && !p.startsWith('{') && !p.startsWith('['));
  }
}

// 5. Ultimate Fallback: If everything else fails, use the whole text as 1 prompt
if (!Array.isArray(prompts) || prompts.length === 0) {
  if (typeof raw === 'string' && raw.trim().length > 0) {
    prompts = [raw.trim()];
  } else {
    prompts = ['Default image prompt']; // Guaranteed non-empty output
  }
}

// Output each prompt as an individual n8n item
return prompts.map((prompt, index) => ({
  json: { prompt: String(prompt), imageIndex: index + 1 }
}));

// Loop through all items coming from Cloudinary
return $input.all().map(item => {
  const originalUrl = item.json.secure_url;

  // Strip .jpg/.jpeg/.png extension and force Cloudinary f_avif delivery
  const cleanUrl = originalUrl.replace(/\.(jpg|jpeg|png)$/i, '.avif');
  const avifUrl = cleanUrl.replace('/upload/', '/upload/f_avif/');

  return {
    json: {
      ...item.json,
      avif_url: avifUrl
    }
  };
});

parameters.text:
=Generate 8 image prompts for this blog article.
{{ $('On form submission').item.json.Title }}

Article content:
{{ $('write the article').item.json.text }}

Return only the JSON array as specified.

parameters.jsCode:
return $input.all().map((item, index) => {
  const base64Data = item.json.result.image;
  return {
    json: {
      fileName: `blog-image-${index + 1}.png`
    },
    binary: {
      data: {
        data: base64Data,
        mimeType: 'image/png',
        fileName: `blog-image-${index + 1}.png`
      }
    }
  };
});

